import openpyxl
wb = openpyxl.load_workbook('init.xlsx')
ws = wb['problem']
out = []
for r in range(1,11):
    label = ws.cell(r,1).value
    b = ws.cell(r,2).value
    if b is None:
        out.append((label, None))
    else:
        for num in b.split('\n'):
            out.append((label, int(num)))
print(len(out))
for x in out: print(x)
"
